 import (
 	"fmt"
 	"strings"
 )

+func renderWhyCheckpointDetail(detail whyCheckpointDetail) string {
+	var sb strings.Builder
+
+	if detail.Entire.CheckpointID != "" {
+		fmt.Fprintf(&sb, "Checkpoint: %s\n", detail.Entire.CheckpointID)
+	}
+	if detail.Entire.Agent != "" {
+		fmt.Fprintf(&sb, "Agent: %s\n", detail.Entire.Agent)
+	}
+	if detail.Entire.Summary != "" {
+		if detail.Entire.IsFallback {
+			fmt.Fprintf(&sb, "Fallback Summary: %s\n", detail.Entire.Summary)
+		} else {
+			fmt.Fprintf(&sb, "Generated Summary: %s\n", detail.Entire.Summary)
+		}
+	}
+
+	hash := detail.Commit.Hash
+	if hash == "" {
+		hash = detail.Commit.ShortHash
+	}
+	if hash != "" {
+		fmt.Fprintf(&sb, "Commit: %s\n", hash)
+	}
+	if detail.Commit.Author != "" {
+		fmt.Fprintf(&sb, "Author: %s\n", detail.Commit.Author)
+	}
+	if detail.Commit.WhenText != "" {
+		fmt.Fprintf(&sb, "When: %s\n", detail.Commit.WhenText)
+	}
+	if detail.Commit.Subject != "" {
+		fmt.Fprintf(&sb, "Subject: %s\n", detail.Commit.Subject)
+	}
+
+	return sb.String()
+}
