+		Entire: whyEntireInfo{
+			CheckpointID: "a3b2c4d5e6f7",
+			Agent:        "Claude Code",
+			Summary:      "Add graceful interrupt handling to the CLI entrypoint.",
+		},
+	})
+
+	for _, want := range []string{
+		"Checkpoint: a3b2c4d5e6f7",
+		"Agent: Claude Code",
+		"Generated Summary: Add graceful interrupt handling to the CLI entrypoint.",
+		"Commit: b550507521111111111111111111111111111111",
+		"Author: Victor Gutierrez",
+		"When: 2 weeks ago",
+		"Subject: Handle interrupt signals",
+	} {
+		if !strings.Contains(out, want) {
